import React from 'react';
import HeroDentistAnimation from '../components/HeroDentistAnimation.jsx';
import BackgroundCursorAura from '../components/BackgroundCursorAura.js';
import AnimatedBackground from '../components/AnimatedBackground.jsx';

export default function BracesTreatment() {
  return (
    <div className="relative min-h-screen bg-white py-12 overflow-hidden">
      <BackgroundCursorAura />
      <div className="absolute inset-0 pointer-events-none">
        <HeroDentistAnimation />
      </div>
      <div className="relative z-10 p-0">
        {/* Hero Section - Full Width with Liquid Waves */}
        <section className="relative w-screen max-w-none flex flex-col items-center justify-center py-16 bg-white/90 rounded-b-3xl shadow-2xl mb-10 animate-slide-down overflow-hidden">
          <AnimatedBackground />
          <h1 className="text-6xl font-extrabold text-[#f44336] mb-4 drop-shadow-lg animate-pop tracking-tight">Braces Treatment</h1>
          <p className="text-xl text-gray-700 max-w-2xl text-center mb-2 animate-fade-in">Transform your smile with modern orthodontic solutions. Our braces treatments are comfortable, effective, and tailored to you.</p>
        </section>

        {/* Image Grid: 2 columns x 3 rows (6 images) */}
        <section className="w-full flex justify-center items-center mb-10 animate-fade-in">
          <div className="grid grid-cols-2 md:grid-cols-2 gap-8 max-w-3xl w-full px-4">
            {[1,2,3,4,5,6].map((num) => (
              <div key={num} className="w-full h-60 bg-gradient-to-br from-[#f44336] to-red-200 flex items-center justify-center rounded-2xl shadow-xl transform hover:scale-105 transition-transform duration-300 animate-img-pop">
                <img src={`https://source.unsplash.com/400x400/?braces,dental,teeth&sig=${num}`} alt={`Braces ${num}`} className="w-full h-full object-cover rounded-2xl" />
              </div>
            ))}
          </div>
        </section>

        {/* Description Section */}
  <section className="w-full max-w-6xl mx-auto bg-white rounded-2xl shadow-lg px-4 md:px-8 py-8 mb-12 animate-fade-in">
          <h2 className="text-2xl font-bold mb-4 text-[#f44336]">About Braces Treatment</h2>
          <p className="text-gray-800 text-lg leading-relaxed">
            Braces treatment is one of the most effective and widely used orthodontic solutions for correcting misaligned teeth, bite issues, and improving overall dental health. The process involves the use of brackets, wires, and sometimes bands, which work together to gradually move teeth into their ideal positions. Modern braces come in various types, including traditional metal braces, ceramic braces that blend with the natural color of teeth, and clear aligners that offer a nearly invisible option for those seeking a more discreet treatment.
            <br /><br />
            The journey begins with a comprehensive consultation, where the orthodontist evaluates the patient’s dental structure, discusses goals, and creates a personalized treatment plan. Diagnostic tools such as X-rays, photographs, and digital scans are used to map out the movement of teeth. Once the plan is finalized, braces are carefully placed on the teeth, and the wires are adjusted to apply gentle, consistent pressure. Over time, this pressure encourages the teeth to shift, correcting crowding, gaps, overbites, underbites, and other alignment issues.
            <br /><br />
            Regular follow-up appointments are essential throughout the treatment, allowing the orthodontist to monitor progress and make necessary adjustments. These visits also provide an opportunity to address any discomfort and ensure optimal results. The duration of braces treatment varies depending on the complexity of the case, but most patients achieve their desired outcome within 18 to 24 months. During this period, maintaining good oral hygiene is crucial, as braces can make cleaning teeth more challenging. Specialized brushes, floss threaders, and mouth rinses are recommended to keep teeth and gums healthy.
            <br /><br />
            Beyond aesthetics, braces offer significant functional benefits. Properly aligned teeth improve chewing efficiency, reduce the risk of dental injuries, and help prevent issues such as jaw pain and temporomandibular joint (TMJ) disorders. Straight teeth are also easier to clean, reducing the likelihood of cavities and gum disease. For children and teenagers, early intervention with braces can guide jaw growth and prevent more severe problems later in life. Adults, too, can benefit from orthodontic treatment, as advances in technology have made braces more comfortable and accessible than ever before.
            <br /><br />
            At our clinic, we prioritize patient comfort and satisfaction. Our experienced orthodontists use the latest techniques and materials to ensure a smooth treatment experience. We offer flexible scheduling, clear communication, and ongoing support to help patients achieve their best smile. Whether you choose metal braces, ceramic braces, or clear aligners, our team is dedicated to delivering outstanding results tailored to your unique needs. Schedule a consultation today and take the first step toward a healthier, more confident smile with braces treatment.
          </p>
        </section>

        {/* Animations */}
        <style>{`
          @keyframes fade-in {
            from { opacity: 0; }
            to { opacity: 1; }
          }
          .animate-fade-in {
            animation: fade-in 1.2s ease;
          }
          @keyframes slide-down {
            from { transform: translateY(-40px); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
          }
          .animate-slide-down {
            animation: slide-down 1s cubic-bezier(.4,0,.2,1);
          }
          @keyframes pop {
            0% { transform: scale(0.9); }
            60% { transform: scale(1.05); }
            100% { transform: scale(1); }
          }
          .animate-pop {
            animation: pop 0.7s cubic-bezier(.4,0,.2,1);
          }
          @keyframes img-pop {
            0% { transform: scale(0.95); }
            60% { transform: scale(1.08); }
            100% { transform: scale(1); }
          }
          .animate-img-pop {
            animation: img-pop 1.2s cubic-bezier(.4,0,.2,1);
          }
        `}</style>
      </div>
    </div>
  );
}
